    private final Runnable saveDraft=()->{if(ready&&session!=null){PhotoDocument document=session.state();IO.execute(()->{try{files.saveDraft(document);}catch(IOException error){post(()->message("Draft not saved: "+error.getMessage()));}});}};
    private final Runnable accountTimer=new Runnable(){@Override public void run(){if(foreground&&!destroyed){account.checkAsync(false);main.postDelayed(this,30000);}}};
    private final StudioAccount.Listener accountListener=state->{if(!destroyed&&canvas!=null){if(!state.canEdit){finishGesture(true);operation++;busy=false;message("Account unavailable. Your photo remains saved locally. Return to Studio Home to sign in.");}updateEnabled();}};
    private interface Command{void run()throws Exception;}
    @Override public void onCreate(Bundle saved){
        super.onCreate(saved);account=StudioAccount.get(this);
        try{files=new PhotoWorkspaceFiles(this);}catch(IOException error){new AlertDialog.Builder(this).setMessage(error.getMessage()).setPositiveButton("Close",(d,w)->finish()).show();return;}
        Object retained=getLastNonConfigurationInstance();if(retained instanceof PhotoEditingSession){session=(PhotoEditingSession)retained;ready=true;}
        if(saved!=null){pendingSaveId=saved.getString("photo.pending");pendingPng=saved.getBoolean("photo.png");}
        build();account.addListener(accountListener);
        if(!ready){setBusy(true,"Opening Photos…");IO.execute(()->{try{String source=files.readDraft();PhotoDocument initial=source==null?PhotoDocument.blank(1024,768,72,PhotoBitmapEngine.blank(1024,768,Color.TRANSPARENT),"Background"):PhotoDocument.decode(source);post(()->{session=new PhotoEditingSession(initial);ready=true;setBusy(false,"Photos · "+initial.width+" × "+initial.height);refresh(true);});}catch(Exception error){post(()->{setBusy(false,"Photo draft unavailable. Saved projects have not been changed.");newDocumentDialog();});}});}else refresh(true);
    }
    @Override public Object onRetainNonConfigurationInstance(){finishGesture(false);return session;}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(pendingSaveId!=null){out.putString("photo.pending",pendingSaveId);out.putBoolean("photo.png",pendingPng);}}
    @Override public void onConfigurationChanged(Configuration value){super.onConfigurationChanged(value);finishGesture(false);build();if(ready)refresh(true);}
    @Override protected void onResume(){super.onResume();foreground=true;if(account!=null){account.checkAsync(false);main.post(accountTimer);}updateEnabled();}
    @Override protected void onPause(){foreground=false;main.removeCallbacks(accountTimer);finishGesture(false);main.removeCallbacks(saveDraft);if(ready)saveDraft.run();super.onPause();}
    @Override protected void onDestroy(){destroyed=true;operation++;main.removeCallbacksAndMessages(null);if(account!=null)account.removeListener(accountListener);if(displayed!=null){canvas.setImage(null);displayed.recycle();displayed=null;}if(isFinishing()&&files!=null&&pendingSaveId!=null){String id=pendingSaveId;boolean png=pendingPng;IO.execute(()->files.deletePending(id,png));}super.onDestroy();}
    private boolean allowed(){return ready&&!busy&&!destroyed&&account!=null&&account.state().canEdit;}
    private void post(Runnable action){main.post(()->{if(!destroyed&&!isFinishing())action.run();});}
    private void build(){
        if(panelDialog!=null)panelDialog.dismiss();editControls.clear();root=column();root.setBackgroundColor(BG);root.setPadding(dp(8),dp(4),dp(8),dp(4));
        root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(8)+insets.getSystemWindowInsetLeft(),dp(4)+insets.getSystemWindowInsetTop(),dp(8)+insets.getSystemWindowInsetRight(),dp(4)+insets.getSystemWindowInsetBottom());return insets;});setContentView(root);root.requestApplyInsets();
        LinearLayout header=row();header.setGravity(Gravity.CENTER_VERTICAL);header.setBackgroundColor(TOP);header.addView(button("Studio Home",()->finish(),false));title=label("Photos NetVista Studio",16,Color.WHITE,true);header.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));header.addView(button("Files",this::filesMenu,true));root.addView(header);
        LinearLayout actions=row();actions.addView(button("New",this::newDocumentDialog,false));actions.addView(button("Import layer",()->chooseFile(IMPORT_IMAGE,"image/*"),true));undoButton=button("Undo",()->{finishGesture(false);if(session.undo())refresh(false);},true);redoButton=button("Redo",()->{if(session.redo())refresh(false);},true);actions.addView(undoButton);actions.addView(redoButton);actions.addView(button("Save",()->prepareSave(false),true));actions.addView(button("Export PNG",()->prepareSave(true),true));root.addView(horizontal(actions));
        LinearLayout tools=row();for(PhotoCanvasView.Tool tool:PhotoCanvasView.Tool.values())tools.addView(button(tool.name().substring(0,1)+tool.name().substring(1).toLowerCase(Locale.ROOT),()->{canvas.setTool(tool);message(tool==PhotoCanvasView.Tool.HAND?"Hand · drag to pan, pinch to zoom":tool+" · use two fingers to navigate");},true));tools.addView(button("Brush settings",this::brushSettings,true));if(getResources().getConfiguration().screenWidthDp<800){tools.addView(button("Layers",()->{panelTab=0;showPanelSheet();},false));tools.addView(button("Properties",()->{panelTab=1;showPanelSheet();},false));}root.addView(horizontal(tools));
        boolean wide=getResources().getConfiguration().screenWidthDp>=800;wideLayout=wide;LinearLayout work=new LinearLayout(this);work.setOrientation(wide?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);
        canvas=new PhotoCanvasView(this);canvas.setListener(new PhotoCanvasView.Listener(){
            public void select(String id){command(()->session.select(id),false);}
            public void moveStarted(String id){if(allowed())try{session.beginTransaction("Move layer");}catch(IOException error){message(error.getMessage());}}
            public void moveChanged(String id,double x,double y){if(allowed()&&session.isEditing())try{session.position(id,x,y);canvas.setDocument(session.state());requestRender();}catch(IOException error){finishGesture(true);message(error.getMessage());}}
            public void moveFinished(boolean cancelled){finishGesture(cancelled);}
            public void stroke(String id,List<float[]> points,boolean erase){paintStroke(id,points,erase);}
            public void zoomChanged(float value){if(zoomLabel!=null)zoomLabel.setText(String.format(Locale.ROOT,"%.0f%%",value*100));}
        });
        panel=column();panel.setPadding(dp(8),0,dp(8),0);panel.setBackgroundColor(PANEL);
        if(wide){work.addView(canvas,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.MATCH_PARENT,1));work.addView(panel,new LinearLayout.LayoutParams(dp(300),ViewGroup.LayoutParams.MATCH_PARENT));}else{work.addView(canvas,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,0,1));panel.setVisibility(View.GONE);}root.addView(work,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,0,1));
        LinearLayout footer=row();footer.setGravity(Gravity.CENTER_VERTICAL);footer.addView(button("−",()->canvas.zoomBy(.8f),false));zoomLabel=label("100%",12,MUTED,false);footer.addView(zoomLabel);footer.addView(button("+",()->canvas.zoomBy(1.25f),false));footer.addView(button("Fit",()->canvas.fit(),false));status=label("Photos",12,MUTED,false);status.setMaxLines(2);footer.addView(status,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));root.addView(footer);fixedControlCount=editControls.size();refreshPanel();
    }
    private void filesMenu(){if(!allowed())return;new AlertDialog.Builder(this).setTitle("Photos · Files").setItems(new String[]{"New document…","Import image as layer…","Open layered project…","Save layered project…","Export full-resolution PNG…","About this workspace"},(d,index)->{switch(index){case 0:newDocumentDialog();break;case 1:chooseFile(IMPORT_IMAGE,"image/*");break;case 2:confirmReplace(()->chooseFile(OPEN_PHOTO,"*/*"));break;case 3:prepareSave(false);break;case 4:prepareSave(true);break;default:new AlertDialog.Builder(this).setTitle("Photos NetVista Studio").setMessage("Native layered editing. Uses the same .netvistaphoto v2 format as Mac and iPad. Move, pinch zoom, pan, native round brushes/eraser, folders, masks, eight blends and primary adjustments.\n\nAdvanced Core Image-only effects are preserved in project files but not approximated or silently flattened. Photoshop ABR import, selections, clone/heal, crop and adjustment curves are not implemented in this Android workspace yet.").setPositiveButton("Done",null).show();}}).show();}
    private void newDocumentDialog(){
        if(busy||destroyed||!account.state().canEdit)return;
        LinearLayout fields=column();fields.setPadding(dp(20),0,dp(20),0);EditText width=number("Width",1024),height=number("Height",768);fields.addView(label("Canvas size · pixels",14,Color.WHITE,true));fields.addView(width);fields.addView(height);CheckBox white=new CheckBox(this);white.setText("White background (off = transparent)");white.setTextColor(Color.WHITE);white.setMinHeight(dp(44));fields.addView(white);
        LinearLayout presets=row();String[]names={"HD","Square","Portrait","A4"};int[][]sizes={{1920,1080},{1080,1080},{1080,1920},{2480,3508}};for(int i=0;i<names.length;i++){int index=i;presets.addView(button(names[i],()->{width.setText(""+sizes[index][0]);height.setText(""+sizes[index][1]);},false));}fields.addView(horizontal(presets));
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("New photo document").setView(fields).setNegativeButton("Cancel",null).setPositiveButton("Create",null).create();dialog.setOnShowListener(ignored->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{int w=Integer.parseInt(width.getText().toString()),h=Integer.parseInt(height.getText().toString());PhotoDocument.validateSize(w,h);long available=PhotoWorkspaceFiles.renderBudget();if((long)w*h*96>available)throw new IOException("That canvas exceeds this device's current safe working memory. Choose a smaller preset; your current photo stays intact.");int color=white.isChecked()?Color.WHITE:Color.TRANSPARENT;dialog.dismiss();if(ready)confirmReplace(()->createDocument(w,h,color));else createDocument(w,h,color);}catch(Exception error){message(error.getMessage());}}));dialog.show();
    }
    private void createDocument(int w,int h,int color){if(busy||destroyed||!account.state().canEdit)return;long ticket=++operation;setBusy(true,"Creating canvas…");IO.execute(()->{try{PhotoDocument document=PhotoDocument.blank(w,h,72,PhotoBitmapEngine.blank(w,h,color),"Background");post(()->{if(!accept(ticket))return;if(session==null)session=new PhotoEditingSession(document);else try{session.newDocument(document);}catch(IOException error){setBusy(false,error.getMessage());return;}ready=true;setBusy(false,"New document");clearPreview();refresh(true);});}catch(Exception error){post(()->{if(accept(ticket))setBusy(false,error.getMessage());});}});}
    private void confirmReplace(Runnable action){if(!allowed())return;new AlertDialog.Builder(this).setTitle("Keep your current photo?").setMessage("Your private draft will be replaced. Save a layered project first if you want a separate copy. New document can also be undone; opening another project starts its own history.").setNegativeButton("Cancel",null).setNeutralButton("Save copy first",(d,w)->prepareSave(false)).setPositiveButton("Continue",(d,w)->action.run()).show();}
    private void refresh(boolean fit){if(!ready||destroyed)return;canvas.setDocument(session.state());if(fit)canvas.fit();title.setText("Photos · "+session.state().width+" × "+session.state().height);refreshPanel();updateEnabled();requestRender();scheduleDraft();}
    private void refreshPanel(){if(panel==null)return;sliderOwner=null;while(editControls.size()>fixedControlCount)editControls.remove(editControls.size()-1);panel.removeAllViews();LinearLayout tabs=row();tabs.addView(button("Layers",()->{finishGesture(false);panelTab=0;if(!wideLayout&&!panelFloating)showPanelSheet();else refreshPanel();},false));tabs.addView(button("Properties",()->{finishGesture(false);panelTab=1;if(!wideLayout&&!panelFloating)showPanelSheet();else refreshPanel();},false));panel.addView(tabs);if(!wideLayout&&!panelFloating)return;if(!ready||session==null){panel.addView(label("Create or open a photo document.",14,MUTED,false));return;}
        LinearLayout content=column();ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.addView(content);panel.addView(scroll,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,0,1));if(panelTab==0)layersPanel(content);else propertiesPanel(content);updateEnabled();}
    private void showPanelSheet(){if(panelDialog!=null||!ready)return;LinearLayout original=panel,floating=column();floating.setBackgroundColor(PANEL);floating.setMinimumHeight(dp(280));panelFloating=true;panel=floating;AlertDialog dialog=new AlertDialog.Builder(this).setView(floating).setPositiveButton("Back to canvas",null).create();panelDialog=dialog;dialog.setOnDismissListener(d->{finishGesture(false);panelDialog=null;panelFloating=false;panel=original;if(!destroyed)refreshPanel();});refreshPanel();dialog.show();dialog.getWindow().setLayout(ViewGroup.LayoutParams.MATCH_PARENT,Math.max(dp(260),(int)(getResources().getDisplayMetrics().heightPixels*.85)));}
    private void layersPanel(LinearLayout content){LinearLayout actions=row();actions.addView(button("+ Layer",this::newLayer,true));actions.addView(button("Folder",this::groupDialog,true));content.addView(horizontal(actions));PhotoDocument state=session.state();for(PhotoDocument.Layer layer:state.layers){LinearLayout line=row();line.setGravity(Gravity.CENTER_VERTICAL);line.setBackgroundColor(layer.id.equals(state.selectedLayerId)?0xff384655:PANEL);Button visible=button(layer.visible?"◉":"○",()->command(()->session.visible(layer.id,!layer.visible),true),true);visible.setContentDescription((layer.visible?"Hide ":"Show ")+layer.name);line.addView(visible,new LinearLayout.LayoutParams(dp(48),dp(48)));Button name=button((layer.groupId==null?"":"    ")+(layer.group?"▣ ":"")+layer.name+(layer.locked?" · locked":""),()->command(()->session.select(layer.id),true),true);name.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);name.setAllCaps(false);name.setMaxLines(2);name.setContentDescription("Select layer "+layer.name);line.addView(name,new LinearLayout.LayoutParams(0,dp(52),1));line.addView(button("⋯",()->layerMenu(layer.id),true),new LinearLayout.LayoutParams(dp(48),dp(48)));content.addView(line);}}
    private void layerMenu(String id){if(!allowed())return;PhotoDocument.Layer layer=session.state().layer(id);if(layer==null)return;String[]options={"Rename…","Duplicate","Move up","Move down",layer.locked?"Unlock":"Lock","Mask…",layer.group?"Ungroup folder":"Group layer…","Delete"};new AlertDialog.Builder(this).setTitle(layer.name).setItems(options,(d,index)->{switch(index){case 0:rename(id);break;case 1:command(()->session.duplicate(id),true);break;case 2:command(()->session.reorder(id,-1),true);break;case 3:command(()->session.reorder(id,1),true);break;case 4:command(()->session.locked(id,!layer.locked),true);break;case 5:maskMenu(id);break;case 6:if(layer.group)command(()->session.ungroup(id),true);else groupDialog();break;case 7:new AlertDialog.Builder(this).setTitle("Delete "+layer.name+"?").setMessage(layer.group?"The folder and its child layers will be removed. Undo can restore them.":"Undo can restore this layer.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(a,b)->command(()->session.remove(id),true)).show();break;}}).show();}
    private void rename(String id){PhotoDocument.Layer layer=session.state().layer(id);if(layer==null)return;EditText name=new EditText(this);name.setText(layer.name);new AlertDialog.Builder(this).setTitle("Rename layer").setView(name).setNegativeButton("Cancel",null).setPositiveButton("Rename",(d,w)->command(()->session.rename(id,name.getText().toString().trim()),true)).show();}
    private void propertiesPanel(LinearLayout content){PhotoDocument.Layer layer=session.selectedLayer();if(layer==null){content.addView(label("Select a layer in Layers.",14,MUTED,false));return;}String id=layer.id;content.addView(label(layer.name,16,Color.WHITE,true));content.addView(label(layer.group?"Folder · children composite together":layer.pixels.width+" × "+layer.pixels.height+" px",12,MUTED,false));
        range(content,"Opacity",0,1,layer.opacity,100,(value)->session.opacity(id,value));content.addView(button("Blend · "+layer.blendMode,()->new AlertDialog.Builder(this).setTitle("Blend mode").setItems(new String[]{"Normal","Multiply","Screen","Overlay","Soft Light","Darken","Lighten","Color Dodge"},(d,index)->command(()->session.blendMode(id,new String[]{"Normal","Multiply","Screen","Overlay","Soft Light","Darken","Lighten","Color Dodge"}[index]),false)).show(),true));
        if(!layer.group&&!layer.adjustment){content.addView(label("TRANSFORM",12,MUTED,true));numericProperty(content,"Position X",layer.positionX,(value)->session.position(id,value,session.state().layer(id).positionY));numericProperty(content,"Position Y",layer.positionY,(value)->session.position(id,session.state().layer(id).positionX,value));range(content,"Scale %",.01,5,layer.scale,100,value->session.mutateLayer(id,"Scale layer",item->item.withProperty("scale",value)));range(content,"Rotation",-180,180,layer.rotation,1,value->session.mutateLayer(id,"Rotate layer",item->item.withProperty("rotation",value)));}
        content.addView(label("PRIMARY ADJUSTMENTS",12,MUTED,true));try{org.json.JSONObject values=layer.properties().getJSONObject("adjustments");range(content,"Exposure",-4,4,values.getDouble("exposure"),10,value->session.adjustment(id,"exposure",value));range(content,"Brightness",-.5,.5,values.getDouble("brightness"),100,value->session.adjustment(id,"brightness",value));range(content,"Contrast",0,3,values.getDouble("contrast"),100,value->session.adjustment(id,"contrast",value));range(content,"Saturation",0,3,values.getDouble("saturation"),100,value->session.adjustment(id,"saturation",value));}catch(Exception error){content.addView(label(error.getMessage(),12,ACCENT,false));}content.addView(button("Layer actions…",()->layerMenu(id),true));}
    private interface ValueCommand{void apply(double value)throws IOException;}
    private void range(LinearLayout parent,String name,double min,double max,double current,double display,ValueCommand action){
        TextView text=label(name+" · "+format(current*display),13,Color.WHITE,false);parent.addView(text);SeekBar slider=new SeekBar(this);slider.setMax(1000);slider.setProgress((int)Math.round((current-min)/(max-min)*1000));slider.setMinimumHeight(dp(44));slider.setContentDescription("Photo "+name);parent.addView(slider);editControls.add(slider);Object owner=new Object();String layerId=session.state().selectedLayerId;
        boolean[]tracking={false};slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){
            public void onStartTrackingTouch(SeekBar bar){if(!allowed()||!sameSelection(layerId)||bar.getWindowToken()==null)return;finishGesture(false);sliderOwner=owner;try{session.beginTransaction(name);tracking[0]=true;}catch(IOException error){message(error.getMessage());}}
            public void onProgressChanged(SeekBar bar,int progress,boolean user){if(!user||!allowed()||!sameSelection(layerId)||bar.getWindowToken()==null)return;if(tracking[0]&&sliderOwner!=owner)return;double value=min+(max-min)*progress/1000;try{action.apply(value);text.setText(name+" · "+format(value*display));canvas.setDocument(session.state());requestRender();if(!tracking[0]){scheduleDraft();updateEnabled();}}catch(IOException error){message(error.getMessage());}}
            public void onStopTrackingTouch(SeekBar bar){if(tracking[0]&&sliderOwner==owner){session.finishTransaction();sliderOwner=null;tracking[0]=false;refresh(false);}}
        });slider.setOnTouchListener((v,event)->{if(event.getActionMasked()==android.view.MotionEvent.ACTION_CANCEL&&sliderOwner==owner){session.cancelTransaction();sliderOwner=null;tracking[0]=false;refresh(false);}return false;});
    }
    private boolean sameSelection(String id){return session!=null&&java.util.Objects.equals(id,session.state().selectedLayerId);}
    private void numericProperty(LinearLayout parent,String name,double value,ValueCommand action){parent.addView(button(name+" · "+format(value),()->{EditText input=number(name,value);new AlertDialog.Builder(this).setTitle(name).setView(input).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->command(()->action.apply(Double.parseDouble(input.getText().toString())),false)).show();},true));}
    private void command(Command action,boolean layers){if(!allowed())return;try{finishGesture(false);action.run();refresh(false);message(session.lastAction());}catch(Exception error){message(error.getMessage());}}
    private void finishGesture(boolean cancelled){if(session!=null&&session.isEditing()){if(cancelled)session.cancelTransaction();else session.finishTransaction();if(canvas!=null){canvas.setDocument(session.state());requestRender();}scheduleDraft();updateEnabled();}sliderOwner=null;}
    private void newLayer(){if(!allowed())return;PhotoDocument snapshot=session.state();runPixels("Adding transparent layer…",()->PhotoDocument.raster("Layer "+(snapshot.layers.size()+1),PhotoBitmapEngine.blank(snapshot.width,snapshot.height,Color.TRANSPARENT)),layer->session.add(layer));}
    private void groupDialog(){if(!allowed())return;List<PhotoDocument.Layer> choices=new ArrayList<>();for(PhotoDocument.Layer layer:session.state().layers)if(!layer.group&&session.isEditable(layer.id))choices.add(layer);if(choices.isEmpty()){message("Add unlocked image layers before creating a folder.");return;}boolean[]selected=new boolean[choices.size()];String[]names=new String[choices.size()];for(int i=0;i<names.length;i++){names[i]=choices.get(i).name;selected[i]=choices.get(i).id.equals(session.state().selectedLayerId);}new AlertDialog.Builder(this).setTitle("Group layers").setMultiChoiceItems(names,selected,(d,index,checked)->selected[index]=checked).setNegativeButton("Cancel",null).setPositiveButton("Group",(d,w)->{List<String>ids=new ArrayList<>();for(int i=0;i<selected.length;i++)if(selected[i])ids.add(choices.get(i).id);command(()->session.group(ids,"Folder",PhotoBitmapEngine.blank(1,1,Color.TRANSPARENT)),true);}).show();}
    private interface LayerTask{PhotoDocument.Layer produce()throws Exception;}private interface LayerResult{void apply(PhotoDocument.Layer value)throws Exception;}
    private void runPixels(String label,LayerTask task,LayerResult result){if(!allowed())return;finishGesture(false);PhotoDocument before=session.state();long ticket=++operation;setBusy(true,label);IO.execute(()->{try{PhotoDocument.Layer layer=task.produce();post(()->{if(!accept(ticket))return;if(session.state()!=before){setBusy(false,"The photo changed while that operation was running. Try again.");return;}try{result.apply(layer);setBusy(false,"Layer updated");refresh(false);}catch(Exception error){setBusy(false,error.getMessage());}});}catch(Exception|OutOfMemoryError error){post(()->{if(accept(ticket))setBusy(false,error instanceof OutOfMemoryError?"Insufficient memory. Your original layer remains intact.":error.getMessage());});}});}
    private void maskMenu(String id){PhotoDocument.Layer original=session.state().layer(id);if(original==null||original.group||original.adjustment){message("Choose an image layer for a pixel-aligned mask.");return;}new AlertDialog.Builder(this).setTitle("Layer mask").setItems(new String[]{"Reveal all","Hide all","Invert existing mask","Paint mask","Paint image","Remove mask"},(d,index)->{if(index==3){if(original.mask==null){message("Add a reveal or hide mask first.");return;}command(()->session.select(id),false);paintMask=true;canvas.setTool(PhotoCanvasView.Tool.BRUSH);if(panelDialog!=null)panelDialog.dismiss();message("Painting mask · white reveals, black conceals");return;}if(index==4){paintMask=false;message("Brush targets image pixels");return;}if(index==5){command(()->session.mask(id,null),true);paintMask=false;return;}if(index==2&&original.mask==null){message("This layer has no mask to invert.");return;}runPixels("Updating layer mask…",()->{if(index<2)return original.withMask(PhotoBitmapEngine.blank(original.pixels.width,original.pixels.height,index==0?Color.WHITE:Color.BLACK));Bitmap bitmap=PhotoBitmapEngine.decode(original.mask),output=null;try{output=bitmap.copy(Bitmap.Config.ARGB_8888,true);if(output==null)throw new IOException("Insufficient memory to invert this mask.");int[]row=new int[output.getWidth()];for(int y=0;y<output.getHeight();y++){output.getPixels(row,0,row.length,0,y,row.length,1);for(int x=0;x<row.length;x++){int p=row[x];row[x]=Color.argb(Color.alpha(p),255-Color.red(p),255-Color.green(p),255-Color.blue(p));}output.setPixels(row,0,row.length,0,y,row.length,1);}return original.withMask(PhotoBitmapEngine.pixels(output));}finally{bitmap.recycle();if(output!=null)output.recycle();}},layer->session.mask(id,layer.mask));}).show();}
    private void brushSettings(){LinearLayout content=column();content.setPadding(dp(16),0,dp(16),0);brushSetting(content,"Size",1,500,brushSize,value->brushSize=value);brushSetting(content,"Hardness",0,1,brushHardness,value->brushHardness=value);brushSetting(content,"Opacity",.01f,1,brushOpacity,value->brushOpacity=value);brushSetting(content,"Flow",.01f,1,brushFlow,value->brushFlow=value);LinearLayout colors=row();int[]swatches={Color.BLACK,Color.WHITE,0xfff05b5e,0xff4c9aff,0xff52c790,0xffffcc55};for(int color:swatches){Button swatch=button("●",()->{brushColor=color;message("Brush colour selected");},false);swatch.setTextColor(color);colors.addView(swatch,new LinearLayout.LayoutParams(dp(44),dp(44)));}content.addView(horizontal(colors));EditText custom=new EditText(this);custom.setHint("Custom colour #RRGGBB");custom.setSingleLine(true);content.addView(custom);content.addView(button("Use custom colour",()->{try{brushColor=Color.parseColor(custom.getText().toString().trim());message("Brush colour selected");}catch(IllegalArgumentException error){message("Enter a colour such as #4C9AFF.");}},false));new AlertDialog.Builder(this).setTitle("Round brush · same controls for eraser").setView(content).setPositiveButton("Done",null).show();}
    private interface FloatResult{void apply(float value);}
    private void brushSetting(LinearLayout parent,String name,float min,float max,float value,FloatResult changed){TextView text=label(name+" · "+format(value),13,Color.WHITE,false);parent.addView(text);SeekBar slider=new SeekBar(this);slider.setMax(1000);slider.setProgress(Math.round((value-min)/(max-min)*1000));slider.setMinimumHeight(dp(44));parent.addView(slider);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}public void onProgressChanged(SeekBar bar,int p,boolean user){if(user){float v=min+(max-min)*p/1000;changed.apply(v);text.setText(name+" · "+format(v));}}});}
    private void paintStroke(String id,List<float[]>points,boolean erase){if(!allowed()||points.isEmpty())return;PhotoDocument.Layer layer=session.state().layer(id);if(layer==null||layer.group||layer.adjustment||!session.isEditable(id))return;PhotoDocument document=session.state();float size=brushSize,hardness=brushHardness,opacity=brushOpacity,flow=brushFlow;int color=brushColor;boolean maskTarget=paintMask;if(maskTarget&&layer.mask==null){message("Add a mask first, or choose Paint image in the mask menu.");return;}
        runPixels(erase?"Erasing layer…":maskTarget?"Painting mask…":"Painting layer…",()->{if((long)layer.pixels.width*layer.pixels.height*20>PhotoWorkspaceFiles.renderBudget())throw new IOException("This layer exceeds the current safe brush working memory. Your original pixels remain intact.");Bitmap source=PhotoBitmapEngine.decode(maskTarget?layer.mask:layer.pixels),pixels=null;try{pixels=source.copy(Bitmap.Config.ARGB_8888,true);if(pixels==null)throw new IOException("Insufficient memory to paint this layer.");Canvas target=new Canvas(pixels);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(color);paint.setAlpha(Math.round(opacity*flow*255));if(erase)paint.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.DST_OUT));float radius=Math.max(.5f,size/(float)layer.scale/2);boolean mirrored=!maskTarget&&layer.properties().getJSONObject("adjustments").getBoolean("mirrored");
            if(hardness<.999f){int core=(color&0xffffff)|0xff000000,edge=color&0xffffff;paint.setShader(new RadialGradient(0,0,radius,new int[]{core,core,edge},new float[]{0,Math.min(.999f,hardness),1},Shader.TileMode.CLAMP));}
            float[]previous=null;int stamps=0;for(float[]point:points){double[]local=layer.sourcePoint(point[0],point[1],document.width,document.height);float x=(float)(mirrored?layer.pixels.width-local[0]:local[0]),y=(float)(layer.pixels.height-local[1]);if(previous==null){stamp(target,paint,x,y,radius);stamps++;}else{float dx=x-previous[0],dy=y-previous[1];int steps=Math.max(1,Math.min(4096,(int)Math.ceil(Math.hypot(dx,dy)/Math.max(.5,radius*.15))));if(stamps+steps>200000)throw new IOException("This stroke is too long. Use shorter strokes; the original layer has not changed.");for(int n=1;n<=steps;n++)stamp(target,paint,previous[0]+dx*n/steps,previous[1]+dy*n/steps,radius);stamps+=steps;}previous=new float[]{x,y};}PhotoDocument.Pixels result=PhotoBitmapEngine.pixels(pixels);return maskTarget?layer.withMask(result):layer.withPixels(result);}finally{source.recycle();if(pixels!=null)pixels.recycle();}},value->{if(maskTarget)session.mask(id,value.mask);else session.pixels(id,value.pixels);});}
    private static void stamp(Canvas target,Paint paint,float x,float y,float radius){target.save();target.translate(x,y);target.drawCircle(0,0,radius,paint);target.restore();}
    private void chooseFile(int request,String type){if(!allowed())return;finishGesture(false);Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(type).addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(intent,request);}catch(RuntimeException error){message("No Files provider is available on this device.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);Uri uri=data==null?null:data.getData();if(request==SAVE_PHOTO||request==EXPORT_PNG){String id=pendingSaveId;boolean png=pendingPng;pendingSaveId=null;if(id==null)return;if(result!=RESULT_OK||uri==null||!allowed()){IO.execute(()->files.deletePending(id,png));message("Photo save cancelled. The document remains in this app.");return;}long ticket=++operation;setBusy(true,"Writing to Files…");IO.execute(()->{try{files.deliver(id,png,uri);post(()->{if(accept(ticket))setBusy(false,png?"Full-resolution PNG exported":"Layered project saved");});}catch(Exception error){post(()->{if(accept(ticket))setBusy(false,"Save failed: "+error.getMessage());});}finally{files.deletePending(id,png);}});return;}
        if(result!=RESULT_OK||uri==null||!allowed())return;
        if(request==IMPORT_IMAGE)importImage(uri);else if(request==OPEN_PHOTO){long ticket=++operation;setBusy(true,"Opening layered project…");IO.execute(()->{try{String json=files.readProject(uri);PhotoDocument candidate=PhotoDocument.decode(json);post(()->{if(!accept(ticket))return;session=new PhotoEditingSession(candidate);clearPreview();setBusy(false,"Layered project opened");refresh(true);});}catch(Exception error){post(()->{if(accept(ticket))setBusy(false,error.getMessage());});}});}}
    private void importImage(Uri uri){if(!allowed())return;PhotoDocument snapshot=session.state();runPixels("Importing image layer…",()->{byte[]bytes;try(InputStream input=getContentResolver().openInputStream(uri)){bytes=PhotoWorkspaceFiles.read(input,Math.max(1,PhotoWorkspaceFiles.renderBudget()/4));}Bitmap image=PhotoImageImport.decode(bytes,PhotoWorkspaceFiles.renderBudget());try{PhotoDocument.Layer layer=PhotoDocument.raster("Imported image",PhotoBitmapEngine.pixels(image));double scale=Math.min(1,Math.min(snapshot.width/(double)image.getWidth(),snapshot.height/(double)image.getHeight()));return layer.withProperty("scale",scale);}finally{image.recycle();}},layer->session.add(layer));}
    private void prepareSave(boolean png){if(!allowed()||pendingSaveId!=null)return;finishGesture(false);PhotoDocument snapshot=session.state();long ticket=++operation;setBusy(true,png?"Rendering full-resolution PNG…":"Preparing layered project…");IO.execute(()->{try{String id=files.prepare(snapshot,png);main.post(()->{if(!accept(ticket)||!foreground){IO.execute(()->files.deletePending(id,png));if(accept(ticket))setBusy(false,"Save paused. Press Save again when Photos is visible.");return;}pendingSaveId=id;pendingPng=png;setBusy(false,"Choose where to save");try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(png?"image/png":"application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,png?"NetVista Photo.png":"NetVista Photo.netvistaphoto"),png?EXPORT_PNG:SAVE_PHOTO);}catch(RuntimeException error){pendingSaveId=null;IO.execute(()->files.deletePending(id,png));message("No Files provider is available.");}});}catch(Exception error){post(()->{if(accept(ticket))setBusy(false,error.getMessage());});}});}
    private boolean accept(long ticket){return !destroyed&&!isFinishing()&&operation==ticket&&account.state().canEdit;}
    private void requestRender(){if(!ready||destroyed)return;wantedRender=session.state();wantedRevision=session.revision();if(rendering)return;renderNext();}
    private void renderNext(){if(wantedRender==null||destroyed)return;PhotoDocument snapshot=wantedRender;long revision=wantedRevision;int maxSide=Math.min(1400,Math.max(512,Math.max(canvas.getWidth(),canvas.getHeight())));wantedRender=null;rendering=true;IO.execute(()->{Bitmap bitmap=null;String error=null;try{bitmap=PhotoBitmapEngine.render(snapshot,maxSide,PhotoWorkspaceFiles.renderBudget());}catch(Exception failure){error=failure.getMessage();}Bitmap complete=bitmap;String failure=error;main.post(()->{rendering=false;if(destroyed||isFinishing()){if(complete!=null)complete.recycle();return;}if(session.state()==snapshot&&session.revision()==revision){if(complete!=null){Bitmap old=displayed;displayed=complete;canvas.setImage(complete);renderedRevision=revision;if(old!=null)old.recycle();}else{clearPreview();message(failure);}}else if(complete!=null)complete.recycle();if(wantedRender!=null)renderNext();});});}
    private void clearPreview(){if(canvas!=null)canvas.setImage(null);if(displayed!=null){displayed.recycle();displayed=null;}renderedRevision=-1;}
    private void scheduleDraft(){if(ready&&!destroyed){main.removeCallbacks(saveDraft);main.postDelayed(saveDraft,600);}}
    private void setBusy(boolean value,String text){busy=value;message(text);updateEnabled();}
    private void updateEnabled(){boolean can=allowed();for(View control:editControls)control.setEnabled(can);if(canvas!=null)canvas.setEditingEnabled(can);if(undoButton!=null)undoButton.setEnabled(can&&session.canUndo());if(redoButton!=null)redoButton.setEnabled(can&&session.canRedo());}
    private void message(String text){if(status!=null)status.setText(text==null?"Photo operation failed":text);}
    private String format(double value){return String.format(Locale.ROOT,"%.2f",value);}
    private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout value=new LinearLayout(this);value.setOrientation(LinearLayout.VERTICAL);return value;}
    private LinearLayout row(){LinearLayout value=new LinearLayout(this);value.setOrientation(LinearLayout.HORIZONTAL);return value;}
    private HorizontalScrollView horizontal(View value){HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);scroll.addView(value);return scroll;}
    private TextView label(String text,int size,int color,boolean bold){TextView view=new TextView(this);view.setText(text);view.setTextSize(size);view.setTextColor(color);view.setGravity(Gravity.CENTER_VERTICAL);view.setPadding(dp(6),dp(5),dp(6),dp(5));if(bold)view.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return view;}
    private Button button(String text,Runnable action,boolean edit){Button button=new Button(this);button.setText(text);button.setTextSize(12);button.setAllCaps(false);button.setTextColor(Color.WHITE);button.setMinWidth(dp(44));button.setMinimumWidth(dp(44));button.setMinHeight(dp(44));button.setMinimumHeight(dp(44));button.setPadding(dp(10),0,dp(10),0);GradientDrawable background=new GradientDrawable();background.setColor(CONTROL);background.setCornerRadius(dp(5));button.setBackground(background);button.setOnClickListener(v->{if(!edit||allowed())action.run();});LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,dp(44));params.setMargins(dp(2),dp(2),dp(2),dp(2));button.setLayoutParams(params);if(edit)editControls.add(button);return button;}
    private EditText number(String hint,double value){EditText field=new EditText(this);field.setHint(hint);field.setText(Math.floor(value)==value?""+(int)value:""+value);field.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);field.setSingleLine(true);field.setMinimumHeight(dp(44));return field;}
